// [Input] Process argv generated by Claude Agent SDK stream-json transports.
// [Output] Validated Runtime options needed by the clean-room SDK/session/MCP integration.
// [Pos] CLI argument boundary; unsupported options fail closed instead of silently changing the upstream CLI contract.
// [Sync] 2026-09-12: restore documented kebab-case tool aliases and reject unknown options.

import { parseEffortLevel, type EffortLevel } from "./request.ts";

export interface RuntimeOptions {
  allowedTools: string[];
  appendSystemPrompt: string[];
  disallowedTools: string[];
  effort: EffortLevel | undefined;
  forkSession: boolean;
  includePartialMessages: boolean;
  inputFormat: string | undefined;
  model: string;
  maxTurns: number;
  outputFormat: string | undefined;
  permissionMode: string;
  pluginDirectories: string[];
  resume: string | undefined;
  sessionId: string | undefined;
  settings: string | undefined;
  systemPrompt: string;
  systemPromptFile: string | undefined;
  tools: string[] | undefined;
}

const VALUE_OPTIONS = new Set([
  "--add-dir",
  "--allowedTools",
  "--allowed-tools",
  "--append-system-prompt",
  "--betas",
  "--disallowedTools",
  "--disallowed-tools",
  "--effort",
  "--fallback-model",
  "--input-format",
  "--json-schema",
  "--max-budget-usd",
  "--max-thinking-tokens",
  "--max-turns",
  "--mcp-config",
  "--model",
  "--output-format",
  "--permission-mode",
  "--permission-prompt-tool",
  "--plugin-dir",
  "--setting-sources",
  "--settings",
  "--system-prompt",
  "--system-prompt-file",
  "--task-budget",
  "--thinking",
  "--thinking-display",
  "--tools",
]);

const BOOLEAN_OPTIONS = new Set([
  "-p",
  "--continue",
  "--debug",
  "--debug-to-stderr",
  "--fork-session",
  "--include-hook-events",
  "--include-partial-messages",
  "--print",
  "--session-mirror",
  "--strict-mcp-config",
  "--verbose",
]);

function optionValue(
  values: Map<string, string[]>,
  name: string,
): string | undefined {
  return values.get(name)?.at(-1);
}

function requireValue(argv: string[], index: number, option: string): string {
  const value = argv[index + 1];
  if (value === undefined || value.startsWith("--")) {
    throw new Error(`${option} requires a value`);
  }
  return value;
}

function positiveIntegerOption(value: string | undefined, fallback: number): number {
  if (value === undefined) return fallback;
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed <= 0 || parsed > 1_000) {
    throw new Error("--max-turns must be an integer between 1 and 1000");
  }
  return parsed;
}

export function parseRuntimeArgv(argv: string[]): RuntimeOptions {
  const values = new Map<string, string[]>();
  const flags = new Set<string>();

  const addValue = (name: string, value: string): void => {
    const existing = values.get(name) ?? [];
    existing.push(value);
    values.set(name, existing);
  };

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    const equals = token.startsWith("--") ? token.indexOf("=") : -1;
    const name = equals > 0 ? token.slice(0, equals) : token;
    if (equals > 0) {
      if (!VALUE_OPTIONS.has(name) && name !== "--resume" && name !== "--session-id") {
        throw new Error(`unsupported option: ${name}`);
      }
      addValue(name, token.slice(equals + 1));
      continue;
    }
    if (VALUE_OPTIONS.has(name)) {
      addValue(name, requireValue(argv, index, name));
      index += 1;
      continue;
    }
    if (BOOLEAN_OPTIONS.has(name)) {
      flags.add(name);
      continue;
    }
    if (name === "-r" || name === "--resume" || name === "--session-id") {
      addValue(name, requireValue(argv, index, name));
      index += 1;
      continue;
    }
    if (name.startsWith("-")) throw new Error(`unsupported option: ${name}`);
  }

  const inputFormat = optionValue(values, "--input-format");
  const outputFormat = optionValue(values, "--output-format");
  if (inputFormat !== undefined && inputFormat !== "stream-json") {
    throw new Error("clean-room Runtime requires --input-format stream-json");
  }
  if (outputFormat !== undefined && outputFormat !== "stream-json") {
    throw new Error("clean-room Runtime requires --output-format stream-json");
  }

  const rawTools = optionValue(values, "--tools");
  const tools = rawTools === undefined || rawTools === "default"
    ? undefined
    : rawTools.split(",").map((name) => name.trim()).filter(Boolean);

  return {
    allowedTools: [
      ...(values.get("--allowedTools") ?? []),
      ...(values.get("--allowed-tools") ?? []),
    ],
    appendSystemPrompt: values.get("--append-system-prompt") ?? [],
    disallowedTools: [
      ...(values.get("--disallowedTools") ?? []),
      ...(values.get("--disallowed-tools") ?? []),
    ],
    effort: parseEffortLevel(optionValue(values, "--effort"), "--effort"),
    forkSession: flags.has("--fork-session"),
    includePartialMessages: flags.has("--include-partial-messages"),
    inputFormat,
    model:
      optionValue(values, "--model") ||
      process.env.ANTHROPIC_MODEL ||
      "claude-sonnet-4-5",
    maxTurns: positiveIntegerOption(optionValue(values, "--max-turns"), 100),
    outputFormat,
    permissionMode: optionValue(values, "--permission-mode") || "default",
    pluginDirectories: values.get("--plugin-dir") ?? [],
    resume: optionValue(values, "--resume") ?? optionValue(values, "-r"),
    sessionId: optionValue(values, "--session-id"),
    settings: optionValue(values, "--settings"),
    systemPrompt: optionValue(values, "--system-prompt") ?? "",
    systemPromptFile: optionValue(values, "--system-prompt-file"),
    tools,
  };
}
